def bound(root):
    record=json.loads((root/'docs/artwork-six-scene-delivery-reviews.json').read_bytes())
    canonical=(json.dumps(record,sort_keys=True,separators=(',',':'),ensure_ascii=False)+'\n').encode()
    if sha(canonical)!='d0f106b8850c9335707af686e37150c0dbfaac115f053e9d69a10416744485f3':raise ValueError('Six-scene current family record changed')
    for review in record['reviews']:
        if sha((root/review['path']).read_bytes())!=review['sha256']:raise ValueError('Six-scene review changed')
def legacy_text(route,text,root):
    if route not in ROWS:return text
    bound(root);row=ROWS[route]
    from continue_motion_binding import restore
    text=restore(route,text.encode()).decode()
    from continue_motion_binding import restore
    if sha(restore(route,(root/route).read_bytes()))!=row['current_sha256']:raise ValueError('Six-scene owner bytes changed')
    for after,before in reversed(row['reverse']):
        if text.count(after)!=1:raise ValueError('Six-scene inverse missing/duplicate/changed exact addition')
        text=text.replace(after,before,1)
    return text
def legacy_reviews(route,entries,root):
    if route not in NEW_REVIEWS:return entries
    bound(root);new=NEW_REVIEWS[route]
    if len([r for r in entries if r.get('asset')==new['asset']])!=1 or entries[-1]!=new:raise ValueError('Six-scene technical review addition changed')
    return entries[:-1]
class Links(HTMLParser):
    def __init__(self,text):super().__init__();self.refs=[];self.feed(text)
    def handle_starttag(self,tag,attrs):
        attrs=dict(attrs)
        if any('six-scene-artwork.css' in attrs.get(k,'') for k in ['href','src']):self.refs.append((tag,attrs))
def reviewed_style(data,sources):
    if sha(data)!='658c22fa104b970fe652961c5c13a860cc593e125b2b3102a591a826510ce311':return False
    consumers={r:t for r,t in sources.items() if 'six-scene-artwork.css' in t}
    if set(consumers)!=set(LINKS):return False
    return all(t.count('six-scene-artwork.css')==1 and Links(t).refs==[('link',{'rel':'stylesheet','href':LINKS[r]})] for r,t in consumers.items())
